// Map over each input item and extract the desired fields
const items = $input.all().map(item => {
  const data = item.json.data || {};
  const username = data.username;
  const profileLink = username ? `https://www.instagram.com/${username}/` : null;

  return {
    json: {
      profile_pic_url: data.profile_pic_url,
      username: username,
      profile_link: profileLink,
      biography: data.biography,
      follower_count: data.follower_count,
      following_count: data.following_count,
      media_count: data.media_count,
    }
  };
});

return items;

const items = $input.all().flatMap(item => {
  const entries = item.json.data?.items || [];
  return entries.map(entry => {
    return {
      json: {
        username: entry.username
      }
    };
  });
});

return items;

